#!/usr/bin/env node
// Prints the active publishable API key generated by the Medusa seed.
// Used by start.sh to hand the key to the storefront container.
const { Client } = require("pg")

async function main() {
  const client = new Client({ connectionString: process.env.DATABASE_URL })
  await client.connect()
  const { rows } = await client.query(
    "SELECT token FROM api_key WHERE type = 'publishable' AND revoked_at IS NULL ORDER BY created_at ASC LIMIT 1"
  )
  await client.end()
  if (rows[0]?.token) {
    process.stdout.write(rows[0].token)
  }
}

main().catch((err) => {
  console.error(err.message)
  process.exit(1)
})
